Bit decode:

```c
static inline unsigned rc_bit(rc_t *rc, uint16_t *prob) {
    uint32_t bound = (rc->range >> 11) * *prob;
    unsigned bit;
    if (rc->code < bound) {
        rc->range = bound;
        *prob += (2048 - *prob) >> 5;
        bit = 0;
    } else {
        rc->code -= bound;
        rc->range -= bound;
        *prob -= *prob >> 5;
        bit = 1;
    }
    if (rc->range < RC_TOP_VALUE) { rc->range <<= 8; rc->code = (rc->code << 8) | rc_read_byte(rc); }
    return bit;
}
```

Bit tree:

```c
static unsigned rc_bittree(rc_t *rc, uint16_t *probs, unsigned nbits) {
    unsigned m = 1;
    for (unsigned i = 0; i < nbits; i++)
        m = (m << 1) | rc_bit(rc, &probs[m]);
    return m - (1u << nbits);
}
static unsigned rc_bittree_reverse(...) {
    unsigned m = 1, sym = 0;
    for (i...) { unsigned b = rc_bit(rc,&probs[m]); m = (m<<1)|b; sym |= b << i; }
    return sym;
}
static uint32_t rc_direct(rc_t *rc, unsigned nbits) {
    uint32_t res = 0;
    do {
        if (range < TOP) normalize;
        range >>= 1;
        code -= range;
        uint32_t t = 0 - (code >> 31);
        code += range & t;
        res = (res << 1) + t + 1;
    } while (--nbits);
    return res;
}
