```c
static uint32_t rc_direct(rc_dec *rc, unsigned nbits)
{
    uint32_t result = 0;
    do {
        rc_normalize(rc);
        rc->range >>= 1;
        rc->code -= rc->range;
        uint32_t t = 0 - (rc->code >> 31);
        rc->code += rc->range & t;
        result = (result << 1) + t + 1;
    } while (--nbits != 0);
    return result;
}
```

