static unsigned rc_bittree(rc_dec *rc, uint16_t *probs, unsigned nbits)
{
    unsigned m = 1;
    for (unsigned i = 0; i < nbits; i++)
        m = (m << 1) + rc_bit(rc, &probs[m]);
    return m - (1u << nbits);
}
static unsigned rc_bittree_reverse(rc_dec *rc, uint16_t *probs, unsigned nbits)
{
    unsigned m = 1, sym = 0;
    for (unsigned i = 0; i < nbits; i++) {
        unsigned b = rc_bit(rc, &probs[m]);
        m = (m << 1) + b;
        sym |= b << i;
    }
    return sym;
}
