 *    pos_slot[4][64], spec_pos reverse tree for short aligned slots,
 *    align[16] tree, literal coder with lc/lp context (0x300 probs per
 *    context, matched-literal decoding when state >= 7), and two length
 *    coders (choice/choice2/low/mid/high per pos_state).
 *  - A match distance is valid only when it is smaller than both the
 *    number of bytes decoded since the last dictionary reset and the
 *    dictionary size.
 *
 * LZMA2 chunk layer:
 *  - 0x00 end; 0x01/0x02 uncompressed chunk (with/without dict reset);
 *    0x80..0xFF LZMA chunk (0x80 no reset, 0xA0 state reset, 0xC0 also
 *    new props, 0xE0 also dict reset). Sizes are big-endian, stored - 1.
 *  - The first chunk must reset the dictionary; an LZMA chunk may not
 *    appear before props have been set; an LZMA chunk without state
 *    reset may not follow an uncompressed chunk. (All verified against
 *    the reference decoder.)
 */
#include "lzma_dec.h"

#include <stdlib.h>
#include <string.h>

/* ------------------------------------------------------------------ */
/* Range decoder                                                       */
/* ------------------------------------------------------------------ */

#define RC_TOP_VALUE (UINT32_C(1) << 24)

#define PROB_INIT 1024
#define PROB_MOVE 5

typedef struct {
	const uint8_t *buf;	/* input buffer */
	size_t pos;		/* next byte to read */
	size_t limit;		/* end of usable input (exclusive) */
	uint32_t range;
	uint32_t code;
	bool eof;		/* set when a read went past limit */
} rc_dec;

static uint32_t rc_read_byte(rc_dec *rc)
{
	if (rc->pos < rc->limit)
		return rc->buf[rc->pos++];

	/* Feed a constant so decoding stays deterministic; the caller
	 * checks rc->eof and reports LZD_EOF. */
	rc->eof = true;
	return 0xFF;
}

static void rc_normalize(rc_dec *rc)
{
	if (rc->range < RC_TOP_VALUE) {
		rc->range <<= 8;
		rc->code = (rc->code << 8) | rc_read_byte(rc);
	}
}

static unsigned rc_bit(rc_dec *rc, uint16_t *prob)
{
	const uint32_t bound = (rc->range >> 11) * *prob;
	unsigned bit;

	if (rc->code < bound) {
		rc->range = bound;
		*prob += (2048 - *prob) >> PROB_MOVE;
		bit = 0;
	} else {
		rc->code -= bound;
		rc->range -= bound;
		*prob -= *prob >> PROB_MOVE;
		bit = 1;
	}

	rc_normalize(rc);
	return bit;
}

static unsigned rc_bittree(rc_dec *rc, uint16_t *probs, unsigned nbits)
{
	unsigned m = 1;

	for (unsigned i = 0; i < nbits; i++)
		m = (m << 1) + rc_bit(rc, &probs[m]);

	return m - (1U << nbits);
}

static unsigned rc_bittree_reverse(rc_dec *rc, uint16_t *probs,
		unsigned nbits)
{
	unsigned m = 1;
	unsigned sym = 0;

	for (unsigned i = 0; i < nbits; i++) {
		const unsigned bit = rc_bit(rc, &probs[m]);
		m = (m << 1) + bit;
		sym |= bit << i;
	}

	return sym;
}

static uint32_t rc_direct(rc_dec *rc, unsigned nbits)
{
	uint32_t result = 0;

	do {
		rc_normalize(rc);
		rc->range >>= 1;
		rc->code -= rc->range;
		const uint32_t t = 0 - (rc->code >> 31);
		rc->code += rc->range & t;
		result = (result << 1) + t + 1;
	} while (--nbits != 0);

	return result;
}

/* ------------------------------------------------------------------ */
/* LZMA probability model and decoder state                            */
/* ------------------------------------------------------------------ */

#define STATES 12
#define POS_STATES_MAX 16	/* 1 << 4 (pb max) */
#define LIT_PROBS_MAX (0x300 << 4)	/* lc + lp <= 4 */
#define MATCH_LEN_MIN 2
#define DIST_MODEL_START 4
#define DIST_MODEL_END 14
#define ALIGN_BITS 4
/*
 * spec_pos cells are indexed by (dist_base - slot + m), m in [1, 31].
 * The maximum index is reached at slot 13: 96 - 13 + 31 = 114.
 */
#define SPEC_POS_SIZE 115

typedef struct {
	uint16_t choice;
	uint16_t choice2;
	uint16_t low[POS_STATES_MAX][8];
	uint16_t mid[POS_STATES_MAX][8];
	uint16_t high[256];
} len_probs;

typedef struct {
	uint16_t is_match[STATES][POS_STATES_MAX];
	uint16_t is_rep[STATES];
	uint16_t is_rep_g0[STATES];
	uint16_t is_rep_g1[STATES];
	uint16_t is_rep_g2[STATES];
	uint16_t is_rep0_long[STATES][POS_STATES_MAX];
	uint16_t pos_slot[4][64];
	uint16_t spec_pos[SPEC_POS_SIZE];
	uint16_t align_dec[1 << ALIGN_BITS];
	uint16_t literal[LIT_PROBS_MAX];
	len_probs match_len;
	len_probs rep_len;
} lzma_probs;

typedef struct {
	rc_dec rc;
	uint8_t *out;		/* output buffer (dictionary window) */
	size_t out_cap;		/* its capacity */
	size_t pos;		/* absolute write position in out */
	size_t dict_start;	/* out index of the last dict reset */
	uint32_t dict_size;
	unsigned lc;
	uint32_t lp_mask;
	uint32_t pb_mask;
	uint32_t state;
	uint32_t rep0, rep1, rep2, rep3;
} lzma_dec;

static void lzma_reset_state(lzma_dec *d, lzma_probs *p)
{
	/* lzma_probs consists solely of uint16_t arrays. */
	uint16_t *a = (uint16_t *)p;
	const size_t n = sizeof(*p) / sizeof(uint16_t);

	for (size_t i = 0; i < n; i++)
		a[i] = PROB_INIT;

	d->state = 0;
	d->rep0 = d->rep1 = d->rep2 = d->rep3 = 0;
}

static unsigned len_decode(rc_dec *rc, len_probs *lp, unsigned pos_state)
{
	if (rc_bit(rc, &lp->choice) == 0)
		return rc_bittree(rc, lp->low[pos_state], 3);

	if (rc_bit(rc, &lp->choice2) == 0)
		return 8 + rc_bittree(rc, lp->mid[pos_state], 3);

	return 16 + rc_bittree(rc, lp->high, 8);
}

/*
 * Decode symbols until d->pos reaches target.
 *
 * allow_marker: an end-of-stream marker (distance 0xFFFFFFFF) terminates
 *   decoding with *saw_marker set and LZD_OK returned; when false, a
 *   marker is LZD_DATA.
 * one_symbol: decode exactly one symbol; used to probe for an optional
 *   end marker after a known-size LZMA1 stream. Any symbol other than a
 *   marker yields LZD_DATA (before producing output).
 * target_is_buffer: target is the output buffer capacity (unknown-size
 *   LZMA1); overrunning it is LZD_BUF instead of LZD_DATA.
 *
 * When the range decoder ran out of real input (rc->eof), LZD_EOF is
 * returned instead of LZD_DATA: conclusions drawn from phantom bytes
 * are unreliable and truncation is the more accurate diagnosis.
 */
static int lzma_run(lzma_dec *d, lzma_probs *p, size_t target,
		bool allow_marker, bool one_symbol, bool target_is_buffer,
		bool *saw_marker)
{
	rc_dec *rc = &d->rc;

	*saw_marker = false;

	while (d->pos < target) {
		const size_t dpos = d->pos - d->dict_start;
		const unsigned pos_state = (unsigned)(dpos & d->pb_mask);
		const uint32_t state = d->state;
		unsigned len;

		if (rc_bit(rc, &p->is_match[state][pos_state]) == 0) {
			/* Literal */
			const unsigned prev = dpos == 0 ? 0 : d->out[d->pos - 1];
			const unsigned lit_state =
					((unsigned)(dpos & d->lp_mask) << d->lc)
					+ (prev >> (8 - d->lc));
			uint16_t *probs = &p->literal[0x300 * lit_state];
			unsigned sym = 1;

			if (state < 7) {
				while (sym < 0x100)
					sym = (sym << 1)
						+ rc_bit(rc, &probs[sym]);
			} else {
				/* Literal with a matched byte context */
				if ((uint64_t)d->rep0 >= (uint64_t)dpos)
					return rc->eof ? LZD_EOF : LZD_DATA;

				unsigned match_byte =
						d->out[d->pos - d->rep0 - 1];
				do {
					match_byte <<= 1;
					const unsigned match_bit =
							match_byte & 0x100;
					const unsigned bit = rc_bit(rc,
						&probs[0x100 + match_bit + sym]);
					sym = (sym << 1) + bit;
					if (match_bit != (bit << 8)) {
						while (sym < 0x100)
							sym = (sym << 1)
								+ rc_bit(rc,
								&probs[sym]);
						break;
					}
				} while (sym < 0x100);
			}

			if (one_symbol)
				return rc->eof ? LZD_EOF : LZD_DATA;

			d->out[d->pos++] = (uint8_t)sym;
			d->state = state < 4 ? 0
					: (state < 10 ? state - 3 : state - 6);
			continue;
		}

		if (rc_bit(rc, &p->is_rep[state]) != 0) {
			/* Repeated match */
			if (rc_bit(rc, &p->is_rep_g0[state]) == 0) {
				if (rc_bit(rc,
					&p->is_rep0_long[state][pos_state])
						== 0) {
					/* Short rep: one byte at rep0 */
					d->state = state < 7 ? 9 : 11;
					if ((uint64_t)d->rep0 >= (uint64_t)dpos
						|| d->rep0 >= d->dict_size)
						return rc->eof ? LZD_EOF
								: LZD_DATA;
					if (one_symbol)
						return rc->eof ? LZD_EOF
								: LZD_DATA;
					d->out[d->pos] =
						d->out[d->pos - d->rep0 - 1];
					d->pos++;
					continue;
				}
			} else {
				uint32_t dist;

				if (rc_bit(rc, &p->is_rep_g1[state]) == 0) {
					dist = d->rep1;
				} else {
					if (rc_bit(rc, &p->is_rep_g2[state])
							== 0) {
						dist = d->rep2;
					} else {
						dist = d->rep3;
						d->rep3 = d->rep2;
					}
					d->rep2 = d->rep1;
				}
				d->rep1 = d->rep0;
				d->rep0 = dist;
			}

			len = len_decode(rc, &p->rep_len, pos_state);
			d->state = state < 7 ? 8 : 11;
		} else {
			/* New match */
			uint32_t dist;
			unsigned slot;

			d->rep3 = d->rep2;
			d->rep2 = d->rep1;
			d->rep1 = d->rep0;

			len = len_decode(rc, &p->match_len, pos_state);
			slot = rc_bittree(rc,
					p->pos_slot[len < 4 ? len : 3], 6);

			if (slot < DIST_MODEL_START) {
				dist = slot;
			} else {
				const unsigned nbits = (slot >> 1) - 1;
				dist = (2U | (slot & 1)) << nbits;
				if (slot < DIST_MODEL_END) {
					dist += rc_bittree_reverse(rc,
						&p->spec_pos[dist - slot],
						nbits);
				} else {
					dist += rc_direct(rc, nbits - ALIGN_BITS)
							<< ALIGN_BITS;
					dist += rc_bittree_reverse(rc,
						p->align_dec, ALIGN_BITS);
				}
			}

			d->rep0 = dist;

			if (dist == UINT32_MAX) {
				/* End-of-stream marker */
				if (!allow_marker)
					return rc->eof ? LZD_EOF : LZD_DATA;
				*saw_marker = true;
				return LZD_OK;
			}

			d->state = state < 7 ? 7 : 10;
		}

		/* A distance is valid only when it refers to a byte that
		 * actually exists in the dictionary window. */
		if ((uint64_t)d->rep0 >= (uint64_t)dpos
				|| d->rep0 >= d->dict_size)
			return rc->eof ? LZD_EOF : LZD_DATA;

		len += MATCH_LEN_MIN;
		if ((uint64_t)len > (uint64_t)(target - d->pos)) {
			if (rc->eof)
				return LZD_EOF;
			return target_is_buffer ? LZD_BUF : LZD_DATA;
		}

		if (one_symbol)
			return rc->eof ? LZD_EOF : LZD_DATA;

		for (unsigned i = 0; i < len; i++) {
			d->out[d->pos] = d->out[d->pos - d->rep0 - 1];
			d->pos++;
		}
	}

	return LZD_OK;
}

/* ------------------------------------------------------------------ */
/* Common helpers                                                      */
/* ------------------------------------------------------------------ */

static bool options_valid(uint32_t dict_size, unsigned lc, unsigned lp,
		unsigned pb)
{
	/* XZ-compatible restriction: lc + lp <= 4, each <= 4, pb <= 4,
	 * dictionary at least 4 KiB. */
	return lc <= 4 && lp <= 4 && lc + lp <= 4 && pb <= 4
			&& dict_size >= 4096;
}

static uint32_t read_be16(const uint8_t *b)
{
	return ((uint32_t)b[0] << 8) | b[1];
}

/* Initialize the range decoder; the caller has verified that at least
 * 5 bytes are available at *p_in. */
static int rc_init(rc_dec *rc, const uint8_t *in, size_t *p_in, size_t limit)
{
	if (in[*p_in] != 0x00)
		return LZD_DATA;

	rc->buf = in;
	rc->code = ((uint32_t)in[*p_in + 1] << 24)
			| ((uint32_t)in[*p_in + 2] << 16)
			| ((uint32_t)in[*p_in + 3] << 8)
			| in[*p_in + 4];
	rc->range = UINT32_MAX;
	rc->pos = *p_in + 5;
	rc->limit = limit;
	rc->eof = false;
	*p_in += 5;
	return LZD_OK;
}

/* ------------------------------------------------------------------ */
/* LZMA2                                                               */
/* ------------------------------------------------------------------ */

int lzma2_decode(const uint8_t *in, size_t in_size, size_t *in_pos,
		uint8_t *out, size_t out_cap, size_t *out_len,
		uint32_t dict_size, unsigned lc, unsigned lp, unsigned pb)
{
	lzma_dec d;
	lzma_probs *probs;
	size_t p_in = *in_pos;
	bool need_dict_reset = true;
	bool need_props = true;
	bool need_state_reset = false;
	int ret = LZD_OK;

	if (!options_valid(dict_size, lc, lp, pb))
		return LZD_OPTIONS;

	probs = malloc(sizeof(*probs));
	if (probs == NULL)
		return LZD_BUF;

	d.out = out;
	d.out_cap = out_cap;
	d.pos = 0;
	d.dict_start = 0;
	d.dict_size = dict_size;
	d.lc = lc;
	d.lp_mask = (UINT32_C(1) << lp) - 1;
	d.pb_mask = (UINT32_C(1) << pb) - 1;
	d.state = 0;
	d.rep0 = d.rep1 = d.rep2 = d.rep3 = 0;

	for (;;) {
		uint8_t control;

		if (p_in >= in_size) {
			ret = LZD_EOF;
			break;
		}
		control = in[p_in++];

		if (control == 0x00) {
			/* End marker; valid even as the whole stream. */
			ret = LZD_OK;
			break;
		}

		if (control == 0x01 || control == 0x02) {
			/* Uncompressed chunk */
			size_t size;

			if (control == 0x01) {
				d.dict_start = d.pos;
				need_dict_reset = false;
			} else if (need_dict_reset) {
				ret = LZD_DATA;
				break;
			}

			if (in_size - p_in < 2) {
				ret = LZD_EOF;
				break;
			}
			size = (size_t)read_be16(in + p_in) + 1;
			p_in += 2;

			if (out_cap - d.pos < size) {
				ret = LZD_BUF;
				break;
			}
			if (in_size - p_in < size) {
				ret = LZD_EOF;
				break;
			}

			memcpy(out + d.pos, in + p_in, size);
			d.pos += size;
			p_in += size;

			/* The next LZMA chunk must reset the state. */
			need_state_reset = true;
			continue;
		}

		if (control < 0x80) {
			ret = LZD_DATA;
			break;
		}

		/* LZMA chunk */
		{
			uint32_t usize, csize;
			size_t chunk_end, target;
			bool saw_marker;

			if (control >= 0xE0) {
				d.dict_start = d.pos;
				need_dict_reset = false;
			} else if (need_dict_reset) {
				ret = LZD_DATA;
				break;
			}

			if (in_size - p_in < 4) {
				ret = LZD_EOF;
				break;
			}
			usize = ((uint32_t)(control & 0x1F) << 16)
					+ read_be16(in + p_in) + 1;
			csize = read_be16(in + p_in + 2) + 1;
			p_in += 4;

			if (control >= 0xC0) {
				/* New properties byte */
				uint8_t pr;
				unsigned nlc, nlp, npb;

				if (p_in >= in_size) {
					ret = LZD_EOF;
					break;
				}
				pr = in[p_in++];
				nlc = pr % 9;
				nlp = (pr / 9) % 5;
				npb = pr / 45;
				if (npb > 4 || nlc + nlp > 4) {
					ret = LZD_DATA;
					break;
				}
				d.lc = nlc;
				d.lp_mask = (UINT32_C(1) << nlp) - 1;
				d.pb_mask = (UINT32_C(1) << npb) - 1;
				need_props = false;
			} else if (need_props) {
				ret = LZD_DATA;
				break;
			}

			if (control >= 0xA0) {
				lzma_reset_state(&d, probs);
				need_state_reset = false;
			} else if (need_state_reset) {
				ret = LZD_DATA;
				break;
			}

			if ((uint64_t)usize > (uint64_t)(out_cap - d.pos)) {
				ret = LZD_BUF;
				break;
			}
			if (in_size - p_in < csize) {
				ret = LZD_EOF;
				break;
			}
			if (csize < 5) {
				ret = LZD_DATA;
				break;
			}

			chunk_end = p_in + csize;
			ret = rc_init(&d.rc, in, &p_in, chunk_end);
			if (ret != LZD_OK)
				break;

			target = d.pos + usize;
			ret = lzma_run(&d, probs, target,
					false, false, false, &saw_marker);
			if (ret != LZD_OK)
				break;

			/* The chunk's compressed data must be consumed
			 * exactly. */
			if (d.rc.pos != chunk_end) {
				ret = LZD_DATA;
				break;
			}

			p_in = chunk_end;
		}
	}

	*in_pos = p_in;
	*out_len = d.pos;
	free(probs);
	return ret;
}

/* ------------------------------------------------------------------ */
/* LZMA1 (.lzma payload and raw LZMA1)                                 */
/* ------------------------------------------------------------------ */

int lzma1_decode(const uint8_t *in, size_t in_size, size_t *in_pos,
		uint8_t *out, size_t out_cap, size_t *out_len,
		uint32_t dict_size, unsigned lc, unsigned lp, unsigned pb,
		uint64_t unpack_size)
{
	lzma_dec d;
	lzma_probs *probs;
	size_t p_in = *in_pos;
	bool saw_marker;
	int ret;

	if (!options_valid(dict_size, lc, lp, pb))
		return LZD_OPTIONS;

	probs = malloc(sizeof(*probs));
	if (probs == NULL)
		return LZD_BUF;

	d.out = out;
	d.out_cap = out_cap;
	d.pos = 0;
	d.dict_start = 0;
	d.dict_size = dict_size;
	d.lc = lc;
	d.lp_mask = (UINT32_C(1) << lp) - 1;
	d.pb_mask = (UINT32_C(1) << pb) - 1;
	lzma_reset_state(&d, probs);

	/* An empty known-size payload needs no range decoder at all. */
	if (unpack_size == 0 && p_in >= in_size) {
		*in_pos = p_in;
		*out_len = 0;
		free(probs);
		return LZD_OK;
	}

	if (in_size - p_in < 5) {
		ret = LZD_EOF;
		goto done;
	}

	ret = rc_init(&d.rc, in, &p_in, in_size);
	if (ret != LZD_OK)
		goto done;

	if (unpack_size != UINT64_MAX) {
		/* Known uncompressed size */
		if (unpack_size > (uint64_t)out_cap) {
			ret = LZD_BUF;
			goto done;
		}

		ret = lzma_run(&d, probs, (size_t)unpack_size,
				false, false, false, &saw_marker);
		if (ret != LZD_OK)
			goto done;
		if (d.rc.eof) {
			ret = LZD_EOF;
			goto done;
		}

		/* An end marker may follow; consume it when present.
		 * Trailing bytes that do not form a marker are an error. */
		if (d.rc.pos < in_size) {
			ret = lzma_run(&d, probs, SIZE_MAX,
					true, true, false, &saw_marker);
			if (ret != LZD_OK)
				goto done;
			if (d.rc.eof) {
				ret = LZD_EOF;
				goto done;
			}
			/* saw_marker is implied by LZD_OK here. */
			p_in = d.rc.pos;
		}
		ret = LZD_OK;
	} else {
		/* Unknown size: decode until the end marker. */
		ret = lzma_run(&d, probs, out_cap,
				true, false, true, &saw_marker);
		if (ret != LZD_OK)
			goto done;
		if (!saw_marker) {
			/* Output buffer filled before any marker. */
			ret = d.rc.eof ? LZD_EOF : LZD_BUF;
			goto done;
		}
		if (d.rc.eof) {
			ret = LZD_EOF;
			goto done;
		}
		p_in = d.rc.pos;
		ret = LZD_OK;
	}

done:
	*in_pos = p_in;
	*out_len = d.pos;
	free(probs);
	return ret;
}
